/**
 * Shared helpers for the differential fuzzer: process running, byte-exact
 * comparison, and an INDEPENDENT decoder for Python's repr(bytes) so that
 * coverage statistics are derived from the reference binary's own output
 * rather than from anything the port produced.
 */

import { execFile } from 'node:child_process';

export const REF = '/workspace/dataset/test17_executable';
export const PORT = '/output/test17.mjs';

/** Run a command, capturing raw stdout/stderr buffers, exit code and signal. */
export function runProc(file, args) {
  return new Promise((resolve) => {
    execFile(
      file,
      args,
      { encoding: 'buffer', maxBuffer: 64 * 1024 * 1024 },
      (err, stdout, stderr) => {
        let code = 0;
        let signal = null;
        if (err) {
          code = typeof err.code === 'number' ? err.code : null;
          signal = err.signal ?? null;
        }
        resolve({ stdout, stderr, code, signal });
      },
    );
  });
}

/** Run the reference binary, retrying the flaky null-status/no-output case. */
export async function runRef(args, attempts = 4) {
  let last = null;
  for (let i = 0; i < attempts; i += 1) {
    last = await runProc(REF, args);
    const flaky =
      (last.code === null || last.signal !== null) &&
      last.stdout.length === 0 &&
      last.stderr.length === 0;
    if (!flaky) return { ...last, retries: i };
  }
  return { ...last, retries: attempts - 1, flakyExhausted: true };
}

export function runPort(args) {
  return runProc(process.execPath, [PORT, ...args]);
}

const PYI = /\[PYI-\d+:ERROR\]/g;
export function normStderr(buf) {
  return buf.toString('binary').replace(PYI, '[PYI-PID:ERROR]');
}

/**
 * Decode one line of Python repr(bytes) back into raw bytes.
 * Deliberately strict: any escape Python is not supposed to emit for bytes
 * (\a \b \v \f \0 \NNN ...) is reported as an anomaly instead of decoded.
 */
export function decodeReprLine(line) {
  const anomalies = [];
  if (line.length < 3 || line[0] !== 'b') {
    return { bytes: null, anomalies: [`no b prefix: ${JSON.stringify(line)}`] };
  }
  const quote = line[1];
  if (quote !== "'" && quote !== '"') {
    return { bytes: null, anomalies: [`bad quote: ${JSON.stringify(line)}`] };
  }
  if (line[line.length - 1] !== quote) {
    return { bytes: null, anomalies: [`unterminated: ${JSON.stringify(line)}`] };
  }
  const body = line.slice(2, -1);
  const out = [];
  for (let i = 0; i < body.length; i += 1) {
    const ch = body[i];
    if (ch !== '\\') {
      const c = ch.charCodeAt(0);
      if (c < 0x20 || c >= 0x7f) anomalies.push(`raw unprintable 0x${c.toString(16)}`);
      if (c === quote.charCodeAt(0)) anomalies.push('unescaped active quote');
      out.push(c);
      continue;
    }
    const nxt = body[i + 1];
    if (nxt === 'x') {
      const hex = body.slice(i + 2, i + 4);
      if (!/^[0-9a-f]{2}$/.test(hex)) {
        anomalies.push(`bad \\x escape: ${JSON.stringify(body.slice(i, i + 4))}`);
        return { bytes: null, anomalies };
      }
      out.push(parseInt(hex, 16));
      i += 3;
    } else if (nxt === 't') { out.push(0x09); i += 1; }
    else if (nxt === 'n') { out.push(0x0a); i += 1; }
    else if (nxt === 'r') { out.push(0x0d); i += 1; }
    else if (nxt === '\\') { out.push(0x5c); i += 1; }
    else if (nxt === "'") { out.push(0x27); i += 1; }
    else if (nxt === '"') { out.push(0x22); i += 1; }
    else {
      anomalies.push(`UNEXPECTED escape \\${nxt} (python should not emit this for bytes)`);
      return { bytes: null, anomalies };
    }
  }
  return { bytes: Uint8Array.from(out), quote, anomalies };
}

/** Fixed-seed PRNG (mulberry32) so every run of the fuzzer is reproducible. */
export function rng(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Printable-ASCII argv value of the given length, never starting with '-'. */
export function randArg(next, len) {
  let s = '';
  for (let i = 0; i < len; i += 1) {
    let c = 0x20 + Math.floor(next() * (0x7f - 0x20));
    if (i === 0 && (c === 0x2d || c === 0x20)) c = 0x41;
    s += String.fromCharCode(c);
  }
  return s;
}

/** Bounded-concurrency map. */
export async function pool(items, width, fn) {
  const results = new Array(items.length);
  let idx = 0;
  const workers = Array.from({ length: Math.min(width, items.length) }, async () => {
    for (;;) {
      const i = idx++;
      if (i >= items.length) return;
      results[i] = await fn(items[i], i);
    }
  });
  await Promise.all(workers);
  return results;
}

/** The coverage conditions the task asks to observe, evaluated per 16-byte block. */

const has = (b, v) => b.includes(v);

export const CONDITIONS = {
  apos_no_quote: (b) => has(b, 0x27) && !has(b, 0x22),
  quote_no_apos: (b) => has(b, 0x22) && !has(b, 0x27),
  both_quotes: (b) => has(b, 0x27) && has(b, 0x22),
  backslash_5c: (b) => has(b, 0x5c),
  tab_09: (b) => has(b, 0x09),
  newline_0a: (b) => has(b, 0x0a),
  carriage_0d: (b) => has(b, 0x0d),
  bell_07: (b) => has(b, 0x07),
  backspace_08: (b) => has(b, 0x08),
  vtab_0b: (b) => has(b, 0x0b),
  formfeed_0c: (b) => has(b, 0x0c),
  nul_00: (b) => has(b, 0x00),
  del_7f: (b) => has(b, 0x7f),
  high_ge_80: (b) => b.some((v) => v >= 0x80),
};

export const CONDITION_NAMES = Object.keys(CONDITIONS);

/**
 * Phase 1 — random differential fuzz.
 *
 * Runs N invocations (each 3 ciphertext blocks) through the reference binary
 * and the port with identical argv, compares stdout byte-for-byte plus exit
 * codes and normalised stderr, and accumulates repr coverage statistics that
 * are decoded from the REFERENCE output.
 */

import { writeFileSync } from 'node:fs';
import { runRef, runPort, normStderr, decodeReprLine, rng, randArg, pool } from './lib.mjs';
import { CONDITIONS, CONDITION_NAMES } from './conditions.mjs';

const N = Number(process.argv[2] ?? 600);
const SEED = Number(process.argv[3] ?? 0xc0ffee);
const WIDTH = Number(process.argv[4] ?? 8);

const next = rng(SEED);
const cases = [];
for (let i = 0; i < N; i += 1) {
  cases.push({
    id: i,
    key: randArg(next, 16),
    iv: randArg(next, 16),
    data: randArg(next, 48),
  });
}

const byteSeen = new Array(256).fill(0);
const condHits = Object.fromEntries(CONDITION_NAMES.map((k) => [k, 0]));
const condExamples = Object.fromEntries(CONDITION_NAMES.map((k) => [k, []]));
const quoteUse = { "'": 0, '"': 0 };
const mismatches = [];
const anomalies = [];
let blocks = 0;
let refRetries = 0;

const results = await pool(cases, WIDTH, async (c) => {
  const args = ['--key', c.key, '--iv', c.iv, '--data', c.data];
  const ref = await runRef(args);
  const port = await runPort(args);

  let bad = null;
  if (!ref.stdout.equals(port.stdout)) bad = 'stdout';
  else if (ref.code !== port.code) bad = 'exit-code';
  else if (normStderr(ref.stderr) !== normStderr(port.stderr)) bad = 'stderr';

  if (bad) {
    // Re-run the reference 3 more times before believing a failure is real.
    const reruns = [];
    for (let k = 0; k < 3; k += 1) reruns.push(await runRef(args));
    const stable = reruns.every((r) => r.stdout.equals(ref.stdout) && r.code === ref.code);
    bad = { kind: bad, stableRef: stable, reruns: reruns.map((r) => ({ code: r.code, out: r.stdout.toString('binary') })) };
  }
  return { c, ref, port, bad };
});

for (const r of results) {
  refRetries += r.ref.retries ?? 0;
  if (r.bad) {
    mismatches.push({
      case: r.c,
      kind: r.bad.kind,
      stableRef: r.bad.stableRef,
      refCode: r.ref.code,
      portCode: r.port.code,
      refOut: r.ref.stdout.toString('binary'),
      portOut: r.port.stdout.toString('binary'),
      refErr: normStderr(r.ref.stderr),
      portErr: normStderr(r.port.stderr),
    });
    continue;
  }
  const text = r.ref.stdout.toString('binary');
  const lines = text.split('\n');
  if (lines.pop() !== '') anomalies.push(`case ${r.c.id}: stdout not newline-terminated`);
  if (lines.length !== 3) anomalies.push(`case ${r.c.id}: ${lines.length} lines, expected 3`);
