  quoteUse,
  refRetries,
  mismatches,
  anomalies,
  condHits,
  condExamples,
  missingBytes,
  byteSeen,
  cases,
};
writeFileSync('/tmp/fuzz/phase1.json', JSON.stringify(report, null, 1));

console.log(`invocations=${N} blocks=${blocks} bytes=${report.bytesObserved}`);
console.log(`mismatches=${mismatches.length} anomalies=${anomalies.length} refRetries=${refRetries}`);
console.log(`quote ' =${quoteUse["'"]}  quote \" =${quoteUse['"']}`);
console.log(`distinct byte values seen: ${256 - missingBytes.length}/256  missing: ${missingBytes.length ? missingBytes.map((v) => '0x' + v.toString(16)).join(',') : 'none'}`);
for (const name of CONDITION_NAMES) console.log(`  ${name.padEnd(16)} ${condHits[name]}`);
