/**
 * Phase 2 — targeted search for rare / adversarial repr(bytes) shapes.
 *
 * The port's AES library is used IN-PROCESS purely as a cheap search oracle to
 * find argv triples whose ciphertext blocks satisfy each target predicate.
 * Every hit is then re-verified by actually spawning the reference binary and
 * the port and comparing their stdout byte-for-byte; the evidence lines quoted
 * in the report come from the reference's stdout, and the predicate is
 * re-checked against bytes decoded from that reference output.
 */

import { writeFileSync } from 'node:fs';
import { AESModeOfOperationCBC } from '/output/lib/aes/index.mjs';
import { runRef, runPort, normStderr, decodeReprLine, rng } from './lib.mjs';

const BUDGET = Number(process.argv[2] ?? 3_000_000); // candidate invocations
const SEED = Number(process.argv[3] ?? 20260810);

const KEY = 'Fuzz.Key.16Bytes';
const IV = 'Fuzz..IV..16Byte';
const isHexDigit = (v) =>
  (v >= 0x30 && v <= 0x39) || (v >= 0x41 && v <= 0x46) || (v >= 0x61 && v <= 0x66);
const cnt = (b, v) => b.reduce((a, x) => a + (x === v ? 1 : 0), 0);
const adj = (b, x, y) => b.some((v, i) => v === x && b[i + 1] === y);

const TARGETS = {
  both_quotes: (b) => b.includes(0x27) && b.includes(0x22),
  apos_quote_backslash: (b) => b.includes(0x27) && b.includes(0x22) && b.includes(0x5c),
  backslash_then_apos: (b) => adj(b, 0x5c, 0x27),
  backslash_then_quote: (b) => adj(b, 0x5c, 0x22),
  backslash_then_x: (b) => adj(b, 0x5c, 0x78),
  backslash_x_hexdigit: (b) => b.some((v, i) => v === 0x5c && b[i + 1] === 0x78 && isHexDigit(b[i + 2])),
  double_backslash: (b) => adj(b, 0x5c, 0x5c),
  apos_last_byte: (b) => b[15] === 0x27,
  apos_first_no_quote: (b) => b[0] === 0x27 && !b.includes(0x22),
  quote_last_with_apos: (b) => b[15] === 0x22 && b.includes(0x27),
  three_apostrophes: (b) => cnt(b, 0x27) >= 3 && !b.includes(0x22),
  two_quotes_no_apos: (b) => cnt(b, 0x22) >= 2 && !b.includes(0x27),
  nul_then_hexdigit: (b) => b.some((v, i) => v === 0x00 && isHexDigit(b[i + 1])),
  bell_then_hexdigit: (b) => b.some((v, i) => v === 0x07 && isHexDigit(b[i + 1])),
  tab_nl_cr_together: (b) => b.includes(0x09) && b.includes(0x0a) && b.includes(0x0d),
  two_of_07_08_0b_0c: (b) => [0x07, 0x08, 0x0b, 0x0c].filter((v) => b.includes(v)).length >= 2,
  three_of_07_08_0b_0c: (b) => [0x07, 0x08, 0x0b, 0x0c].filter((v) => b.includes(v)).length >= 3,
  all_of_07_08_0b_0c: (b) => [0x07, 0x08, 0x0b, 0x0c].every((v) => b.includes(v)),
  del_next_to_apos: (b) => adj(b, 0x7f, 0x27) || adj(b, 0x27, 0x7f),
  nul_and_del_and_high: (b) => b.includes(0x00) && b.includes(0x7f) && b.some((v) => v >= 0x80),
  all_bytes_high: (b) => b.every((v) => v >= 0x80),
  all_bytes_escaped: (b) => b.every((v) => v < 0x20 || v >= 0x7f),
  no_escapes_at_all: (b) => b.every((v) => v >= 0x20 && v < 0x7f && v !== 0x27 && v !== 0x22 && v !== 0x5c),
};
const NAMES = Object.keys(TARGETS);

// ---------------------------------------------------------------- search
const keyBytes = Uint8Array.from(KEY, (c) => c.charCodeAt(0));
const ivBytes = Uint8Array.from(IV, (c) => c.charCodeAt(0));
const aes = new AESModeOfOperationCBC(keyBytes, ivBytes);

const next = rng(SEED);
const data = new Uint8Array(48);
const found = new Map();
let candidates = 0;

const t0 = Date.now();
for (; candidates < BUDGET && found.size < NAMES.length; candidates += 1) {
  for (let i = 0; i < 48; i += 1) {
    let c = 0x20 + Math.floor(next() * 95);
    if (i === 0 && (c === 0x2d || c === 0x20)) c = 0x41;
    data[i] = c;
  }
  aes.lastCipherblock = ivBytes; // reset the CBC chain without re-expanding the key
  const blocks = [];
  for (let i = 0; i < 48; i += 16) blocks.push(Array.from(aes.encrypt(data.subarray(i, i + 16))));

  for (const name of NAMES) {
    if (found.has(name)) continue;
    const idx = blocks.findIndex(TARGETS[name]);
    if (idx >= 0) {
      found.set(name, { data: String.fromCharCode(...data), blockIndex: idx });
    }
  }
}
const searchMs = Date.now() - t0;
const notFound = NAMES.filter((n) => !found.has(n));

// ---------------------------------------------------- differential verify
const verified = [];
const mismatches = [];
for (const [name, hit] of found) {
  const args = ['--key', KEY, '--iv', IV, '--data', hit.data];
  const ref = await runRef(args);
  const port = await runPort(args);

  let bad = null;
  if (!ref.stdout.equals(port.stdout)) bad = 'stdout';
  else if (ref.code !== port.code) bad = 'exit-code';
  else if (normStderr(ref.stderr) !== normStderr(port.stderr)) bad = 'stderr';
  if (bad) {
    const reruns = [];
    for (let k = 0; k < 3; k += 1) reruns.push(await runRef(args));
    mismatches.push({
      name, args, kind: bad,
      refOut: ref.stdout.toString('binary'), portOut: port.stdout.toString('binary'),
      refCode: ref.code, portCode: port.code,
      refErr: normStderr(ref.stderr), portErr: normStderr(port.stderr),
      rerunStable: reruns.every((r) => r.stdout.equals(ref.stdout)),
      rerunOuts: reruns.map((r) => r.stdout.toString('binary')),
    });
    continue;
  }

  const lines = ref.stdout.toString('binary').split('\n').slice(0, -1);
  const line = lines[hit.blockIndex];
  const dec = decodeReprLine(line);
  const holdsInRef = dec.bytes ? TARGETS[name](Array.from(dec.bytes)) : false;
  verified.push({
    name, data: hit.data, blockIndex: hit.blockIndex, line,
    hexOfBlock: dec.bytes ? Array.from(dec.bytes).map((v) => v.toString(16).padStart(2, '0')).join(' ') : null,
    quote: dec.quote, holdsInRef, anomalies: dec.anomalies, allLines: lines,
  });
}

const report = { candidates, searchMs, seed: SEED, key: KEY, iv: IV, notFound, verified, mismatches };
writeFileSync('/tmp/fuzz/phase2.json', JSON.stringify(report, null, 1));

console.log(`candidates=${candidates} (${(candidates * 3).toLocaleString()} blocks) searchMs=${searchMs}`);
console.log(`targets found=${found.size}/${NAMES.length} verified=${verified.length} mismatches=${mismatches.length}`);
console.log(`NOT FOUND: ${notFound.length ? notFound.join(', ') : 'none'}`);
for (const v of verified) {
  console.log(`\n${v.name}  [block ${v.blockIndex + 1}, quote ${v.quote}, predicate-holds-in-reference=${v.holdsInRef}${v.anomalies.length ? ', ANOMALIES ' + v.anomalies.join('|') : ''}]`);
  console.log(`  --data ${JSON.stringify(v.data)}`);
  console.log(`  ref line: ${v.line}`);
  console.log(`  bytes   : ${v.hexOfBlock}`);
}
if (mismatches.length) console.log('\nMISMATCHES\n' + JSON.stringify(mismatches, null, 1));

/**
 * Phase 3 — deterministic edge cases around the repr/CLI boundary: error
 * paths, exit codes, unusual block counts, and inputs that force specific
 * byte values into the ciphertext via multi-byte UTF-8 keys/data.
 */

import { writeFileSync } from 'node:fs';
import { runRef, runPort, normStderr, decodeReprLine } from './lib.mjs';

const CASES = [
  ['sample-1', ['--key', 'Ak.Gz@@He!c(Jd8,', '--iv', 'P#&03h.T(+m5_2XN', '--data', '};}w]2=?1C++Z+Eabi8?X_Iv2e:cAx^plV%)F%mHpL![!,c)']],
