  ['sample-3', ['--key', '_FKMBskR,{E,jWpx', '--iv', 'c.*$.wu  zE.<iDN', '--data', '2N3a>*HW==(w-HRU5;EW@V,&X<BS :cHd<#MKOe5hE6(Z0p@']],
  ['sample-4', ['--key', ':7+ZBj}xgYw<s*#G', '--iv', ')gxmez*lgS03n]Yq', '--data', ')E1cij6 1cX#@7:]+].,UmvhlLEX-bAD6{pt(pzDS%scKBdE']],
  ['quotes-in-argv', ['--key', 'a"b\'c\\d`e f$g<h', '--iv', "x'y\"z\\1234567890", '--data', 'q\'w"e\\r\'t"y\\u\'i"o\\p\'a"s\\d\'f"g\\h\'j"k\\l\'z"x\\c\'v"b\\']],
  ['data-empty', ['--key', '0123456789abcdef', '--iv', 'fedcba9876543210', '--data', '']],
  ['data-1-block', ['--key', '0123456789abcdef', '--iv', 'fedcba9876543210', '--data', 'AAAAAAAAAAAAAAAA']],
  ['data-8-blocks', ['--key', '0123456789abcdef', '--iv', 'fedcba9876543210', '--data', 'ABCDEFGHIJKLMNOP'.repeat(8)]],
  ['data-not-multiple-of-16', ['--key', '0123456789abcdef', '--iv', 'fedcba9876543210', '--data', 'A'.repeat(47)]],
  ['data-17', ['--key', '0123456789abcdef', '--iv', 'fedcba9876543210', '--data', 'A'.repeat(17)]],
