  ['both-key-and-iv-bad', ['--key', 'x', '--iv', 'y', '--data', 'A'.repeat(48)]],
  ['missing-data', ['--key', '0123456789abcdef', '--iv', 'fedcba9876543210']],
  ['no-args', []],
  ['help', ['--help']],
  ['unknown-flag', ['--key', '0123456789abcdef', '--iv', 'fedcba9876543210', '--data', 'A'.repeat(48), '--nope']],
  // multi-byte UTF-8: 8 two-byte chars encode to exactly 16 key bytes
  ['utf8-key-16-bytes', ['--key', 'é'.repeat(8), '--iv', 'ü'.repeat(8), '--data', 'à'.repeat(24)]],
  ['utf8-key-chars-not-bytes', ['--key', 'é'.repeat(16), '--iv', 'fedcba9876543210', '--data', 'A'.repeat(48)]],
  ['utf8-data-mixed', ['--key', '0123456789abcdef', '--iv', 'fedcba9876543210', '--data', 'aéb€c\u{1f600}d'.repeat(4)]],
  ['data-with-newline', ['--key', '0123456789abcdef', '--iv', 'fedcba9876543210', '--data', 'A\nB\tC\rD�EFG HIJKLMNOPQRSTUVWXYZabcdefghijklmn']],
